function validateZabbixParams(requiredParams, allParams) {
	requiredParams.forEach(function (field) {
		if (typeof allParams !== 'object' || typeof allParams[field] === 'undefined' || allParams[field] === '') {
			throw 'Required param is not set: ' + field + '.';
		}
	});
}

function OCI(service, action, params) {
	this.zabbixLogPrefix = '[ OCI ] [ ' + service + ' ] [ ' + action + ' ]';
	this.request = new HttpRequest();

	this.hash = function (string) {
		return sha256(string);
	};

	this.sign = function (string) {
		return sign('sha256', params['private_key'], string);
	};

	this.encode = function (hash) {
		const hexArr = hash.match(/.{1,2}/g);
		var uInt8Array = new Uint8Array(hexArr.length);
		hexArr.forEach(function (hex, idx) {
			uInt8Array[idx] = parseInt(hex, 16);
		});
		return btoa(uInt8Array);
	};

	this.getDate = function () {
		const weekdayShortList = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
		const monthShortList = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
		const today = new Date();
		return weekdayShortList[today.getUTCDay()] + ', ' + today.getUTCDate() + ' ' + monthShortList[today.getUTCMonth()] + ' ' + today.getUTCFullYear() + ' ' + today.getUTCHours() + ':' + today.getUTCMinutes() + ':' + today.getUTCSeconds() + ' GMT';
	};

	this.postRequest = function (apiPath, body) {
		const sigHeaders = '(request-target) date host x-content-sha256 content-type content-length';
		const contentTypeHeader = 'content-type: application/json';
		const dateHeader = 'date: ' + this.getDate();
		const hostHeader = 'host: ' + params['api_host'];
		const requestTarget = '(request-target): post ' + apiPath;
		const bodyHeader = 'x-content-sha256: ' + this.encode(this.hash(body));
		const bodyLengthHeader = 'content-length: ' + body.length;
		const signingString = requestTarget + '\n' + dateHeader + '\n' + hostHeader + '\n' + bodyHeader + '\n' + contentTypeHeader + '\n' + bodyLengthHeader;
		const signature = this.encode(this.sign(signingString));
		const authHeader = 'Authorization: Signature version="1",keyId="' + params['tenancy_ocid'] + '/' + params['user_ocid'] + '/' + params['fingerprint'] + '",algorithm="rsa-sha256",headers="' + sigHeaders + '",signature="' + signature + '"';
		const reqHeaders = [contentTypeHeader, dateHeader, bodyHeader, bodyLengthHeader, authHeader];
		for (var i = 0; i < reqHeaders.length; i++) {
			this.request.addHeader(reqHeaders[i]);
		}
		if (params['http_proxy']) {
			this.request.setProxy(params['http_proxy']);
			Zabbix.log(4, this.zabbixLogPrefix + ' Using proxy: ' + params['http_proxy']);
		}
		const response = this.request.post('https://' + params['api_host'] + apiPath, body);
		this.request.clearHeader();
		if (this.request.getStatus() === parseInt(params['http_status_code'])) {
			return response;
		}
		Zabbix.log(3, this.zabbixLogPrefix + ' HTTP ' + this.request.getStatus() + ': ' + response);
		throw 'Unexpected HTTP response code: ' + this.request.getStatus();
	};
}

function padTwo(n) {
	return ('0' + n).slice(-2);
}

function toISOStr(d) {
	return d.getUTCFullYear() + '-' + padTwo(d.getUTCMonth() + 1) + '-' + padTwo(d.getUTCDate()) + 'T' + padTwo(d.getUTCHours()) + ':' + padTwo(d.getUTCMinutes()) + ':' + padTwo(d.getUTCSeconds()) + 'Z';
}

const params = JSON.parse(value);
validateZabbixParams(['tenancy_ocid', 'user_ocid', 'private_key', 'fingerprint', 'api_host', 'http_status_code'], params);
var oci = new OCI('Billing', 'Get monthly cost', params);

const now = new Date();
const startTime = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
const endTime = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1));
const startTimeStr = toISOStr(startTime);
const endTimeStr = toISOStr(endTime);

const body = JSON.stringify({
	'tenantId': params['tenancy_ocid'],
	'timeUsageStarted': startTimeStr,
	'timeUsageEnded': endTimeStr,
	'granularity': 'MONTHLY',
	'queryType': 'COST'
});

const response = oci.postRequest('/20200107/usage', body);

var data;
try {
	data = JSON.parse(response);
} catch (e) {
	Zabbix.log(3, '[ OCI ] [ Billing ] Could not parse response: ' + response);
	throw 'Could not parse API response.';
}

var totalCost = 0;
var currency = '';
if (data['items'] && Array.isArray(data['items'])) {
	const items = data['items'];
	for (var i = 0; i < items.length; i++) {
		if (items[i]['computedAmount']) {
			totalCost += items[i]['computedAmount'];
		}
		if (!currency && items[i]['currency']) {
			currency = items[i]['currency'];
		}
	}
}
totalCost = Math.round(totalCost * 100) / 100;

return JSON.stringify({
	'cost': totalCost,
	'currency': currency
});
